actions.old_string:
if duplicates:
    offsets = (
        # Avoid numpy conversion (necessary for dask-cudf)
        bisect.bisect_left(seq, x) for x in seq_unique
    )
    enforce_exact = npartitions and len(list(offsets)) >= npartitions
else:
    offsets = seq_unique = None

actions.new_string:
if duplicates:
    # Convert generator to list immediately to avoid consuming it
    offsets = [
        # Avoid numpy conversion (necessary for dask-cudf)
        bisect.bisect_left(seq, x) for x in seq_unique
    ]
    enforce_exact = npartitions and len(offsets) >= npartitions
else:
    offsets = seq_unique = None
